// -- Inicializar alertas dinamicas con datos hardcodeados --
// (se recalculan al cargar el Excel con parseActividadesSheet)
(function initAlertFields() {
  const mesesEjec = DATA.mesesEjec;
  DATA._deficits = [];
  DATA.organos.forEach(function(o) {
    const d = DATA.byOrgano[o];
    for (let i = 0; i < mesesEjec; i++) {
      const p = d.progM[i], e = d.ejecM[i];
      if (p > 0 && e < p) {
        DATA._deficits.push({ org: o, mes: DATA.meses[i], prog: p, ejec: e, diff: e - p });
      }
    }
  });
  DATA._sinEjecucion = DATA.organos.filter(function(o) {
    return DATA.byOrgano[o].acts > 0 && DATA.byOrgano[o].ejec === 0 && DATA.byOrgano[o].prog > 0;
  });
  DATA._cumplidos = DATA.organos.filter(function(o) {
    const d = DATA.byOrgano[o];
    if (d.acts === 0 || mesesEjec === 0 || d.ejec === 0) return false;
    for (let i = 0; i < mesesEjec; i++) {
      if (d.progM[i] > 0 && d.ejecM[i] < d.progM[i]) return false;
    }
    return true;
  });
})();

